// Extrai e prepara os dados recebidos da API Agenda Atende
const body = $input.first().json.body || $input.first().json;

const client = body.client || {};
const appointment = body.appointment || {};
const service = body.service || {};
const professional = body.professional || {};

// Telefone WhatsApp de destino
let phone = client.whatsapp_number || client.phone || "";
phone = phone.replace(/\D/g, ""); // apenas números
if (phone.length === 10 || phone.length === 11) {
  phone = "55" + phone; // prefixo Brasil se necessário
}

// Mensagem formatada enviada pela API
const message = body.formatted_message || `Olá, ${client.name || 'Cliente'}! Seu pagamento foi confirmado com sucesso. Sua reserva #${body.appointment_id || ''} está garantida!`;

return [{
  json: {
    appointment_id: body.appointment_id,
    payment_id: body.payment_id,
    client_name: client.name,
    phone: phone,
    service_name: service.name,
    professional_name: professional.name,
    start_time: appointment.start_time,
    message: message
  }
}];
